{
 "summary": "The Lean theorem states that a finite lattice L with a least element is isomorphic to the full congruence lattice Con(A) of some algebra A on a nonempty finite carrier Fin n (finitely many finitary operations) if and only if there is a nonempty finite colored complete graph. Its coloring c : Fin n → Fin n → L must be symmetric, vanish exactly on the diagonal, satisfy the triangle inequality, be join-dense in L, and satisfy a path condition. The path condition says every pair whose color lies below the join of a nonempty seed set's colors is connected, by an equivalence-closure path, to images of seeds under label-decreasing self-maps. This is a faithful rendering of the characterization in Theorem 1.1(i). The main caveat is that the exact wording of the paper's Theorem 2.2 is not in the excerpt, and the decidability claims and parts (ii)–(iv) are not formalized.",
 "glossary": [
  {"decl": "Algebra", "line": 10, "plain": "An algebra on Carrier with finitely many operations, each of finite arity (arity 0 allowed).", "standard_concept": "finite algebra (universal algebra)", "matches_standard": "partly", "note": "Only finite signatures are allowed. On a finite carrier any set of operations can be replaced by finitely many with the same congruences, since there are only finitely many equivalence relations. So Con-representability is unaffected."},
  {"decl": "Compatible", "line": 15, "plain": "The equivalence relation is preserved coordinatewise by every operation.", "standard_concept": "compatibility of an equivalence with operations", "matches_standard": "yes", "note": ""},
  {"decl": "Congruence", "line": 19, "plain": "Con(A): compatible equivalence relations, ordered by inclusion (the Setoid order).", "standard_concept": "congruence lattice Con(A)", "matches_standard": "yes", "note": ""},
  {"decl": "Representable", "line": 25, "plain": "L ≅ Con(A) as orders, for some algebra A on a nonempty finite set.", "standard_concept": "L = Con(A) for a finite algebra A (full congruence lattice)", "matches_standard": "yes", "note": ""},
  {"decl": "Admissible", "line": 28, "plain": "The self-map f is label-decreasing: c(f x, f y) ≤ c(x, y) for all x, y.", "standard_concept": "label-decreasing self-map", "matches_standard": "yes", "note": ""},
  {"decl": "Marked", "line": 32, "plain": "The ordered pair (l, r) is the image (f s1, f s2) of some seed edge under some label-decreasing f.", "standard_concept": "edge images of seeds", "matches_standard": "yes", "note": ""},
  {"decl": "Connected", "line": 37, "plain": "(l, r) lies in the equivalence relation generated by the marked pairs.", "standard_concept": "path condition via edge-image paths", "matches_standard": "yes", "note": ""},
  {"decl": "IsGraphWitness", "line": 41, "plain": "The coloring is symmetric, c(x, y) = ⊥ iff x = y, satisfies the triangle inequality, and its colors are join-dense in L. It also satisfies the path condition: for every nonempty seed set S, c(x, y) ≤ ⋁_{e∈S} c(e) implies (x, y) is Connected by S.", "standard_concept": "colored-graph criterion of Theorem 2.2", "matches_standard": "unclear", "note": "Theorem 2.2 is not in the excerpt. It is consistent with the description in §1.2 (principal-congruence colors, label-decreasing maps, path condition)."},
  {"decl": "HasGraphWitness", "line": 52, "plain": "Some graph of size n > 0 carries a witness coloring.", "standard_concept": "finite nonempty graph witness", "matches_standard": "yes", "note": ""}
 ],
 "lean_claims": [
  {"theorem": "graph_criterion", "line": 57, "plain": "For every finite lattice L with a bottom element: L ≅ Con(A) for some algebra A on Fin n, n > 0, iff there are n > 0 and c : Fin n → Fin n → L satisfying IsGraphWitness."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1(i)", "plain": "A finite nonempty lattice is representable iff it satisfies the finite colored-graph criterion of Theorem 2.2. For each graph size the criterion is decidable by a finite test."},
  {"ref": "Theorem 1.1(ii)-(iv)", "plain": "Representability is undecidable. There is a minimal nonrepresentable lattice L0 with |L0| > 7. Recognition of full subgroup intervals is undecidable."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1(i) / Theorem 2.2", "lean_theorem": "graph_criterion", "relation": "equivalent", "why": "The iff characterization appears faithful. The per-size decidability remark is not formalized but is trivial for a finite search."},
  {"paper_ref": "Theorem 1.1(ii)-(iv)", "lean_theorem": null, "relation": "not_formalized", "why": "The target is only the graph criterion."}
 ],
 "flags": [
  {"id": "F1", "category": "definition-mismatch", "severity": "low", "decl": "IsGraphWitness", "line": 41, "paper_ref": "Theorem 2.2", "explanation": "The exact statement of Theorem 2.2 is not in the excerpt, so the Lean criterion cannot be compared verbatim. Possible differences include seed nonemptiness, ordered versus unordered seeds, and join-density versus another generation condition. Sketch check: necessity holds with c = principal congruence Cg, since unary polynomials are label-decreasing and Mal'cev chains give the path condition. Sufficiency holds with all label-decreasing maps as operations. So the Lean iff is a correct, standard criterion.", "polarity": "unclear", "probe_idea": "Compare the Lean IsGraphWitness clause-by-clause with the full text of Theorem 2.2."},
  {"id": "F2", "category": "definition-mismatch", "severity": "low", "decl": "Algebra", "line": 10, "paper_ref": "Theorem 1.1(i)", "explanation": "Algebras have finitely many finitary operations. This is harmless for Con on a finite carrier, because finitely many operations suffice to separate the finitely many non-congruences.", "polarity": "n/a", "probe_idea": null},
